from scipy.ndimage import label
def compshapes(g,c):
    lab,n=label(np.array(g)==c,structure=np.ones((3,3)))
    sh=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        h=w=(ys.max()-ys.min()+1),(xs.max()-xs.min()+1)
        sh.append((len(ys),h,w))
    return Counter(sh)
