def adj_comps(g,c):
    lab,n=label(np.array(g)==c,structure=np.ones((3,3)))
    pts=[set(map(tuple,np.where(lab==i))) for i in range(1,n+1)]
    out=[]
    for a in range(len(pts)):
        for b in range(a+1,len(pts)):
            if any(abs(p[0]-q[0])<=1 and abs(p[1]-q[1])<=1 for p,q in zip(pts[a],pts[b])):
                out.append((a,b))
    return out
