import numpy as np
from scipy.ndimage import label
def enclosed(g,c):
    # holes = 0-components not touching border, within complement of c? simpler: count 0-regions fully surrounded by c
    lab,n=label((g==0),structure=np.ones((3,3)))
    res=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        sur=set()
        for y,x in zip(ys,xs):
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<g.shape[0] and 0<=nx<g.shape[1]:
                    sur.add(int(g[ny,nx]))
        res.append((len(ys), sorted(sur)))
    return res
