def hole_comp(g,c):
    g=np.array(g); H,W=g.shape
    lab,nz=label(g==c,structure=np.ones((3,3)))
    res=[]
    for i in range(1,nz+1):
        ys,xs=np.where(lab==i)
        h,w=ys.max()-ys.min()+1,xs.max()-xs.min()+1
        box=g[np.ix_(range(ys.min(),ys.max()+1), range(xs.min(),xs.max()+1))]
        # background cells fully enclosed by this comp within bbox
        holes=[]
        for y,x in zip(*np.where(box==0)):
            # find zero-comp ID at (y,x)
            lab0,k0=label(g==0,structure=np.ones((3,3)))
            if lab0[y,x]==lab0[list(zip(ys.tolist()))[list(np.where(box==0)[0])[0]][0]]: pass
        # simpler: flood fill zeros from outside bbox over whole grid; remaining zeros inside bbox are holes
        ext=set()
        for p in [(0,-1),(0,W),(H,-1),(H,0)]:
            yy,xx=p
            while True:
                for dy,dx in [(1,0),(-1,0),(0,1),(0,-1)]:
                    a,b=yy+dy,xx+dx
                    if 0<=a<H and 0<=b<W and g[a,b]==0 and (a,b) not in ext:
                        ext.add((a,b)); yy,xx=a,b
        for y in range(H):
            for x in range(W):
                if g[y,x]==0 and (y,x) not in ext:
                    # assign to nearest comp
                    best=None
                    for j in range(1,nz+1):
                        Y,X=np.where(lab0==j)
                        if any(abs(y-Y[ii])<2 and abs(x-X[ii])<2 for ii in range(len(Y))):
