                    ys,xs=np.where(lab==best)
                    h,w=ys.max()-ys.min()+1,xs.max()-xs.min()+1
                    key=(len(ys),min(ys.min()))
                    res.append((key,int(h*w),int((g[np.ix_(ys,xs)]==0).sum())))
    return res
